package cli

import "strings"

// Command help is self-contained so agents never need to hand-format Markdown.
func commandHelp(command string) string {
	usage := map[string]string{
		"install":   "install jcode [--all-instances | --jcode-home PATH] [--dry-run] | install commit-msg [--dry-run]",
		"setup":     "setup",
		"uninstall": "uninstall jcode [--all-instances | --jcode-home PATH] [--dry-run] | uninstall commit-msg [--dry-run]",
		"init":      "init", "new": `new "title" --goal "outcome" --accept "observable check" [flags]`,
		"ls":   "ls [--status todo|doing|done|dropped] [--type TYPE] [--priority LABEL] [--label LABEL] [--group FOLDER] [--epic EPIC] [--mine] [--jsonl]",
		"show": "show ID", "edit": "edit ID", "move": "move ID (--before ID | --after ID | --top)", "mv": "mv ID GROUP",
		"take": "take ID --model MODEL [--as NAME]", "done": `done ID [--reflect "TEXT"]`, "reflections": "reflections [--all] | reflections resolve ID N applied|dismissed", "check": "check ID N", "strike": `strike ID N --reason "why"`, "promote": "promote ID N", "note": `note ID "text"`,
		"set":  `set ID [--title "title"] [--type TYPE] [--priority LABEL] [--label LABEL] [--status STATUS] [--assignee NAME] [--parent EPIC|none] [--goal TEXT] [--purpose TEXT] [--principle TEXT] [--details TEXT] [--accept TEXT]...`,
		"drop": `drop ID "reason"`, "wait": `wait ID [--on NAME] "on what"`, "resume": "resume ID", "design": `design ID "question" --for NAME [--as NAME] | design ID --clear`, "dep": "dep ID [--add REF ...] [--remove REF ...]", "next": "next [--type TYPE] [--priority LABEL] [--label LABEL] [--group FOLDER] [--epic EPIC] [--mine]",
		"rebalance": "rebalance [ID ...]", "types": "types", "states": "states", "lint": "lint [ID] [--summary] [--all] [--code [CODE]]", "sync": "sync", "deduce": "deduce [--since REV]", "import": "import backlog DIRECTORY [--dry-run] | import github [OWNER/REPO] [--dry-run] | import files DIR [--cite PREFIX] [--dry-run]", "board": "board [--all] [--wide] [--type TYPE] [--priority LABEL] [--label LABEL] [--group FOLDER] [--epic EPIC] [--mine]", "tui": "tui", "mcp": "mcp", "upgrade": "upgrade", "help": "help [COMMAND]",
	}
	details := map[string]string{
		"setup":       "Prints what an agent needs to switch this repository to huginn, then a checklist of the steps still open, each with the exact command or edit. Reads only; changes nothing. Re-run after each step.\n",
		"install":     "Adds huginn -> hug task mcp to Jcode mcp.json. Keeps a timestamped backup and other servers. Default: JCODE_HOME or ~/.jcode. --all-instances discovers the static zsh registry. Restart Jcode afterward.\ninstall commit-msg: refuse commits without exactly one Model: trailer, the model id that made the\ncommit or Model: human when the git author wrote it (t709he). It goes into this clone's\n<git-common-dir>/hooks; a hook already there keeps running first, as commit-msg.pre-hug. With\ncore.hooksPath (a project's own .githooks) hug never edits the tracked hook: it says which two\nlines to add to it, and hug task setup lists that step until they are there. Merges, rebases,\ncherry-picks, reverts, fixup!/squash! and the hug/tasks and muninn-notes branches are exempt;\nhug's own board commits add Model: from --model or HUG_MODEL. Emergency exit: git commit --no-verify.\nList commits by model: git log --format='%h %(trailers:key=Model,valueonly,separator=%x2C) %s', or one model:\ngit log --grep='^Model: gpt-6.1-sol$'.\n",
		"uninstall":   "Removes only the huginn MCP entry, keeping backups and other servers. Same instance selection as install.\nuninstall commit-msg removes hug's Model: gate and puts back a hook it had kept as commit-msg.pre-hug.\n",
		"new":         "Required: --goal (where we aim), --purpose (why), --principle (what we do and do not do) and at\nleast one --accept TEXT; repeat --accept for each check. --details is optional (only facts a decision\ndepends on). A missing part is named with every other one, and one fix: line gives the whole command.\nOptional: --type feature|bug|chore|spike|docs (default feature), --priority LABEL.\nRepeat --dep REF for dependencies and --label LABEL for labels.\nUse --group FOLDER, --top, or --after REF to choose placement.\nExample: hug task new \"Form\" --goal \"Submit works\" --purpose \"Users save drafts\" --principle \"Server validates\" --accept \"Saved\"\n",
		"ls":          "Columns: id, status, type, slug, title. All statuses are included unless filtered. Filters combine.\n--jsonl prints one JSON task per line; --json one object with a tasks array.\n--mine is the name take records: --as, HUG_USER, the agent session, else --model/HUG_MODEL.\n",
		"show":        "Shows goal, notes, numbered acceptance and dependency ids with current titles/statuses/paths.\nA task with lint findings ends with the same block as hug task lint ID: each finding, then one fix: line.\n",
		"edit":        "Runs $EDITOR, commits the edited task and reports lint findings.\nPrefer check, note and set for non-interactive changes.\n",
		"move":        "Changes filename rank only, repairing neighbouring ranks automatically if needed.\nUse mv to change folder.\n",
		"mv":          "Moves the task to a folder without changing its id, rank or contents.\nExample: hug task mv k7m2qx auth\n",
		"take":        "Pulls, checks dependencies and ownership, sets doing, commits and pushes as a lock.\n--model MODEL is required (or HUG_MODEL): the model doing the work, such as claude-opus-5-5\nor gpt-6.1-sol; a person gives --model human. --as NAME (or HUG_USER, or the agent session,\njcode: the name in JCODE_SESSION_ID) is optional; without a name the assignee is the model.\ngit config user.name is never used. Both are recorded: assignee and model.\nExample: hug task take k7m2qx --as poodle --model claude-opus-5-5\nRepeating take on your own doing task succeeds without changing it.\n",
		"done":        "Only a doing task becomes done: take it first (a todo task is refused with the take as the fix).\nBlocks on open dependencies and unchecked acceptance (exit 3 with exact fixes).\nTick every acceptance item first, or strike out one that no longer applies (hug task strike). There is no --force. Repeating done succeeds.\nDone asks one question: did the instructions (AGENTS.md, tool descriptions, hug messages)\nguide you well, or did one mislead you or leave a gap? --reflect TEXT stores the answer\nas a Reflection note on the task, after done succeeds; quote the instruction and say what\nhappened. \"nothing\" is a fine answer. Repeat done with --reflect to answer afterwards.\n",
		"reflections": "Lists open reflections across the board: task, date, who, the instruction quoted and the text.\n--all includes applied and dismissed ones. A reviewer turns one into an instruction change\n(shown as a diff), then: hug task reflections resolve ID N applied; or dismissed.\nN counts the task's reflections from 1, as listed.\n",
		"promote":     "Turns acceptance item N into its own task, ranked right after ID in the same group and under\nthe same epic (an epic's item becomes its child). The item then reads 'done when task:NEW is done'\nand is ticked automatically when NEW is done.\nExample: hug task promote k7m2qx 2\n",
		"strike":      "Strikes acceptance item N out as not relevant, with --reason (required): why it no longer\napplies. The text stays, crossed through, with the reason, who (--as, HUG_USER, the agent\nsession or --model) and the day: - [ ] ~~TEXT~~ (not relevant: REASON, NAME, DATE).\ndone counts a struck check as settled. --undo restores it as an open check. A ticked item\ncannot be struck (it was done). show prints it as N. [-] ~~TEXT~~ (not relevant: ...).\nExample: hug task strike k7m2qx 2 --reason \"replaced by the API test in item 3\"\n",
		"check":       "Ticks acceptance item N, numbered from 1 in show output. Repeating it succeeds.\nExample: hug task check k7m2qx 1\n",
		"note":        "Appends text to Notes, preserving existing content.\nExample: hug task note k7m2qx \"Blocked on p3rt9a; waiting for API\"\n",
		"set":         "Types: feature|bug|chore|spike|docs. Statuses: todo|doing|done|dropped.\nPriority is a free label. --label and --assignee replace the field with one value.\n--status todo gives your task back (keeping its stage) or reopens a done or dropped one; the old\nnode's fields move to ## History. Status done still enforces dependencies and acceptance. Use take to claim work.\n--parent EPIC puts the task under an epic (epic > task > acceptance item; an epic has no parent);\n--parent none clears it. An epic is done only when its children are done or dropped.\n--goal, --purpose, --principle and --details replace that section's text; --accept (repeatable) adds an\nunchecked item. Every lint fix: line is a set command, so no editor is needed. The reply lists what\nlint still finds on the task, with one fix: line for all of it.\n",
		"dep":         "Add or remove dependency references, stored as immutable ids. Repeat --add/--remove.\nRepeats are no-ops. A dependency cycle blocks with exit 3 and an exact fix.\nA dependency on an epic waits until all its children are done or dropped.\nA condition waits too: --add \"when PREDICATE\" with date YYYY-MM-DD, load below N (5-min average),\nbranch NAME merged, release NAME exists (a tag), task:ID closed, group NAME closed (or --add group:NAME);\nadd \"wakes NAME\" to say who it wakes (default: whoever took the task). next skips the task and take\nrefuses until it holds; a task or group condition also holds back done. Remove it by what it says.\nExample: hug task dep k7m2qx --add p3rt9a\nExample: hug task dep k7m2qx --add \"when load below 120\" --add group:auth\n",
		"drop":        "Marks a task dropped even when blocked, with the reason (dropped_reason). Does not delete the file.\nRepeating it succeeds. hug task set ID --status todo reopens it; the reason moves to ## History.\n",
		"wait":        "Your doing task waits on something outside the board (CI, a reply, a release): stage waiting,\nwaiting_on and waiting_since are written; --on NAME waits on a person (waiting_on \"NAME: what\"), who\nsees it in hug tui as waiting: you. hug task resume ID ends the wait. A dependency on another\ntask is not a wait: hug task dep ID --add OTHER.\n",
		"resume":      "Ends a wait: the waiting fields move to ## History and the stage is set again (active, or what holds).\n",
		"design":      "A question must be answered before anyone starts: stage design, with design_question, design_for (--for:\nthe person who must answer, required), design_since and design_asked_by (--as, HUG_USER or the agent\nsession). The person sees it in hug tui as design: you. --clear when it is answered: the\nquestion moves to ## History and the stage is set again (ready, or what holds).\n",
		"next":        "Plain next: highest-ranked unblocked, unassigned todo that is not an epic (an epic finishes through its children). --epic EPIC limits to that epic. Exit 4 when none match.\n--mine: my unblocked doing first, then todo, in rank order. Filters combine.\nTypes: feature|bug|chore|spike|docs. Priority is a free label.\n",
		"rebalance":   "Rekeys the rank prefix of task filenames (e.g. 000000000003.ID.slug.md becomes 00i.ID.slug.md)\nso later moves have room. Task order, ids and contents do not change; it is one commit,\nundone with git revert in .hug/tasks. Usually unnecessary: move rekeys neighbours itself.\nWith IDs, only the span between them is rekeyed.\n",
		"states":      "Prints the state and stage tree from huginn/internal/task/states.go: each state (does anyone have it?),\nits stages (why nobody works on it, or what happens with it now), who sets each, the fields a node carries\nwhile a task is in it, and the transitions the commands make. --json for the table.\n",
		"lint":        "The board overview: findings per code, then one line per task with its codes and the command that\nshows it: ID  code, code  -> hug task lint ID. More than 30 tasks: the first 10 and how to see the rest.\nhug task lint ID: every finding of that task as file:line: [code] problem, then next: is ONE command\nthat fixes all it can (hug task set ID --purpose \"...\" --principle \"...\"; then hug upgrade).\nNever silent: a clean board says \"no findings\".\n--summary: one line per code with its count, meaning and the command that lists it.\n--code CODE lists one kind finding by finding, each with its fix; --code alone lists every code with its count.\n--all includes done and dropped tasks, which are otherwise hidden and counted (\"N findings on closed tasks hidden\").\nEvery open task is held to the description pattern (Goal, Purpose, Principle, Acceptance).\nCodes include dangling-dependency (depends on an id no task has), not-a-dependency (a Depends on line\nthat is not one), long-title, no-acceptance, parent-too-deep, backlog-leftover (Backlog.md markers or\nunused imported fields; hug upgrade removes them), stale-owner (a doing task whose assignee\nhas had no live jcode session for over 24 h; skipped where the session list is not readable).\nJSON: findings (path, line, problem, code, fix), all of them on open tasks (every task with --all),\ntasks_findings (per task: id, codes, findings, fix), summary (total, codes, hidden, hidden_codes) and hidden.\n",
		"deduce":      "Notes what git says about tickets: a commit whose subject ends with ticket ids, e.g. (16dxsr) or (t709he, 44w1ev), reaching main adds 'landed <sha> on main <date>'; a release tag vX.Y.Z containing it adds 'shipped in vX.Y.Z', or sets done_release on a done ticket.\nEach clone reads only what is new since its last pass; the first pass starts at the current tip. --since REV replays from REV (e.g. v0.7.30). A line is written once per ticket and commit, from any clone.\nIt never ticks a check or marks done. sync and the background pass run it too.",
		"sync":        "Commits local task edits, pulls with rebase and pushes only the task branch (hug/tasks), now.\nYou rarely need it: every change is pushed in the background within seconds (a burst of writes\nis one push), and reads fetch when the last fetch is over 5 s old. Offline or after a conflict,\nhug task ls says 'N unpushed' with this command as the fix; nothing is lost meanwhile.\nHUG_SYNC=off turns the background push off. Its log: .git/hug/sync/hug-tasks.log.\n",
		"upgrade":     "Moves tasks from the old layout (branch huginn at .huginn/) to branch hug/tasks at .hug/tasks/:\nrenames the branch, moves the folder, renames the remote branch. History is unchanged.\nPuts every task's sections in order: Goal, Purpose, Principle, Relevant details, Depends on,\nAcceptance, other sections, Notes, History; no section's text changes. Removes backlog import\nleftovers: <!-- SECTION:... --> and <!-- AC:... --> marker lines and the unused fields created_date,\nordinal, backlog_status and import_type_inference. Prints each removed line. It never moves text\nbetween sections: writing Purpose or Principle stays with the task's author. Safe to run again.\n",
		"import": "Imports or re-syncs backlog-md tasks idempotently, preserving old ids as aliases.\nDIRECTORY is the backlog root (e.g. .backlog: reads tasks, drafts, completed and archive in one run;\nwhen an id is in several folders the newest updated_date wins) or a single folder of task files.\nRe-running merges backlog changes; edits made in huginn win. --dry-run reports without writing.\n" +
			"import github reads every issue (open and closed) of OWNER/REPO, or of this repository, through the gh CLI:\n" +
			"alias GH-<number>, labels and assignees kept, task-list checkboxes become acceptance items,\n" +
			"closed becomes done, closed as not planned becomes dropped. Re-run to sync; huginn edits win.\n",
		"tui":   "Interactive ranked list and board. For non-interactive output use board or ls --json.\n",
		"board": "Prints todo, doing and done side by side in rank order; blocked tasks are marked.\nDone shows the last 5 unless --all. Filters match ls. --json gives the columns.\n",
		"mcp":   "Runs the standard-I/O MCP server with ten flat tools and next-step hints.\n",
	}
	return "hug task " + usage[command] + "\n" + details[command] + "Refs accept ids, unique prefixes, slugs and aliases case-insensitively.\nAdd --json for structured output.\nnext: hug task next\n"
}
func isJSONL(args []string) bool {
	for _, a := range args {
		if a == "--jsonl" {
			return true
		}
	}
	return false
}
func isJSON(args []string) bool {
	for _, a := range args {
		if a == "--json" || strings.HasPrefix(a, "--json=") {
			return true
		}
	}
	return false
}
